mapper.select:
SELECT detail_id, task_id, book_number, book_name, subtitle, author1, author2, author, isbn, publish_location, publisher, publish_date, target_audience, content_summary, classification_number, language, hit_sensitive, hit_problem_book, is_whitelist_publisher, risk_level, sensitive_words, detection_time, check_status, error_message, created_time, updated_time FROM booklist_check_detail
task_id = #{taskId}
AND risk_level = #{riskLevel}
AND (hit_sensitive = 1 OR hit_problem_book = 1 OR is_whitelist_publisher = 0)
ORDER BY detail_id ASC
